import json, pathlib, wave, sys
ROOT=pathlib.Path(__file__).parent
# Screen captures are from the running product, all records are demonstrative.
scenes=[
('01-login','Модус Трейд · Фидбек','Сквозной рабочий процесс','Обращение → решение → подтверждение','Пример: маркировка мест хранения','Перед вами Фидбек — сервис обратной связи для сотрудников Модус Трейд. Покажем весь путь предложения: от подачи до результата, который подтверждает сам сотрудник. Все данные и события в этом примере демонстрационные.'),
('02-form','Предложение сотрудника','Сотрудник','Понятная идея из ежедневной работы','Тип: идея\nКатегория: склад и логистика','Сотрудник предлагает добавить крупные ярлыки на полки с похожими товарами. На ярлыке будут артикул, название и фотография. Начать можно с одной полки. Автору не нужно заранее знать, кому поручить рассмотрение.'),
('03-preview','Проверка перед отправкой','Сотрудник','Автор контролирует содержание','Заголовок и описание\nПредпросмотр перед подачей','Перед отправкой система показывает итоговое обращение. Сотрудник проверяет заголовок, описание и категорию. При необходимости он возвращается к редактированию. Обращение отправляется только после его собственного подтверждения.'),
('04-received','Предложение принято','Сотрудник','Обращение не теряется','Номер MT-000018\nСтатус: Получено','Предложение сохранено и получило номер. В карточке видны описание, переписка и история. Пока ответственный не назначен, система честно показывает это. Сотрудник может вернуться сюда и проверить дальнейшее движение обращения.'),
('05-queue','Предложение в очереди','Координатор','Единая точка распределения','Поиск по номеру\nОтветственный пока не назначен','Теперь входим как координатор. Предложение находится в общей очереди. Поиск по номеру помогает быстро найти нужную запись. Координатор видит статус, автора и отсутствие ответственного, поэтому понятно, какое действие требуется дальше.'),
('06-assignment','Ответственный и срок','Координатор','У предложения появляется владелец','Кто рассматривает\nКогда ждать следующий ответ','Координатор выбирает ответственного и устанавливает дату следующего ответа. Комментарий объясняет задачу: проверить крупные ярлыки на одной полке и запросить оценку автора. Назначение и срок сохраняются в истории и доступны сотруднику.'),
('07-work','Принятие в работу','Ответственный','Рассмотрение переходит к действию','Статус: В работе\nСрок ответа сохранён','Ответственный открывает назначенное ему предложение и принимает его в работу. Теперь автор видит, что обращением занимаются. Важен не сам факт прочтения: у предложения уже есть исполнитель, срок и следующий конкретный шаг.'),
('08-message','Обсуждение в карточке','Ответственный','Контекст остаётся рядом с идеей','Сообщения доступны обеим сторонам\nНичего не нужно искать в чатах','Ответственный пишет автору, что начнёт с одной полки и проверит читаемость ярлыков. Переписка остаётся в карточке предложения. Здесь можно уточнить детали и согласовать действия, сохраняя общий контекст обращения.'),
('09-plan','План небольшой проверки','Ответственный','Сначала проверяем на одной полке','Гипотеза и изменение\nСрок и критерий успеха','Для идеи создаётся небольшой эксперимент. Формулируем гипотезу: крупные ярлыки помогут различать похожие товары. Описываем изменение, задаём срок и критерий успеха. В нашем примере сотрудник должен находить нужные коробки без дополнительного уточнения.'),
('10-active','Эксперимент запущен','Ответственный','Одобрение идеи ещё не результат','Проверяем ограниченное изменение\nПлан доступен в обращении','После утверждения план становится активным экспериментом. В реальной работе теперь нужно подготовить ярлыки, разместить их и провести проверку. В ролике этот период сокращён монтажом: мы демонстрируем состояния системы, а не реальный производственный замер.'),
('11-finish','Фиксация наблюдений','Ответственный','Записываем, что действительно сделано','Действия и наблюдения\nВыбор итога проверки','Когда проверка закончена, ответственный записывает выполненные действия и полученные наблюдения. Для демонстрации указываем, что на одной полке размещены крупные ярлыки. Итог — внедрить шире. Это сценарий показа, а не подтверждённый результат работы компании.'),
('12-experiment','Итог эксперимента','Ответственный','Наблюдения отделены от цифр','Нет замеров — нет численного эффекта\nОбращение ещё не закрыто','Результат проверки сохранён в карточке. Мы не вводили численных измерений, поэтому система показывает: количественный эффект не подтверждён. Она не придумывает экономию или рост производительности. Завершение эксперимента само по себе ещё не закрывает обращение.'),
('13-result','Решение по предложению','Ответственный','Результат нужно объяснить автору','Что выполнено\nЧто предлагается делать дальше','Теперь ответственный фиксирует выполнение по самому обращению. В решении описаны ярлыки, место проверки и дальнейшее предложение распространить подход на похожие места хранения. Это сообщение увидит автор и сможет оценить результат со своей стороны.'),
('14-awaiting','Ожидание подтверждения','Ответственный','Исполнитель не закрывает вопрос за автора','Статус: Ожидает подтверждения\nСледующий шаг — у сотрудника','После сохранения решения предложение переходит в ожидание подтверждения. Ответственный сообщил о выполнении, но окончательный результат ещё должен оценить сотрудник. Молчание автора не считается успехом и не приводит к автоматическому закрытию.'),
('15-notification','Автор получает обновление','Сотрудник','Можно вернуться к своему предложению','Уведомление о результате\nПереход в нужную карточку','Возвращаемся в кабинет сотрудника. В центре уведомлений появляется обновление по предложению. Переход открывает нужную карточку, где рядом находятся описание, переписка, эксперимент и зафиксированное решение.'),
('16-confirm','Результат оценивает автор','Сотрудник','Помогло — или нужна доработка','Помогло → закрыть\nПроблема осталась → вернуть в работу','Сотрудник знакомится с результатом и оставляет оценку. Если изменение помогло, он подтверждает выполнение. Если проблема осталась, можно вернуть обращение в работу с комментарием. В этом демонстрационном сценарии сотрудник подтверждает удобство маркировки.'),
('17-closed','Предложение закрыто','Сотрудник','Есть подтверждение и история','Статус: Закрыто\nРезультат подтверждён автором','После подтверждения автора предложение получает статус Закрыто. В карточке остаются решение, итог эксперимента, переписка и история изменений. Видно не только то, что обращение когда-то подали, но и как по нему пришли к результату.'),
('18-history','От идеи — к проверенному изменению','Модус Трейд · Фидбек','Один понятный цикл','Сотрудник → координатор → ответственный\nРезультат → подтверждение сотрудника','Так работает полный цикл Фидбека: сотрудник предлагает улучшение, координатор назначает ответственного, исполнитель проверяет решение, а автор подтверждает результат. Демонстрационный пример завершён. Реальную эффективность изменения нужно проверять в работе компании.')
]
records=[]
for i,(screen,title,role,thesis,bullets,narration) in enumerate(scenes):
 records.append(dict(index=i+1,screen=screen+'.png',title=title,role=role,thesis=thesis,bullets=bullets.split('\n'),narration=narration))
(ROOT/'storyboard.json').write_text(json.dumps(records,ensure_ascii=False,indent=2))
if '--audio' in sys.argv:
 from piper import PiperVoice, SynthesisConfig
 voice=PiperVoice.load('/tmp/modus-irina.onnx')
 cfg=SynthesisConfig(length_scale=1.04)
 for rec in records:
  p=ROOT/'audio'/f'{rec["index"]:02}.wav'
  with wave.open(str(p),'wb') as f: voice.synthesize_wav(rec['narration'],f,syn_config=cfg)
  print('audio',rec['index'],flush=True)
